const japanese=/[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}]/u;
const counted=(text,pattern,render)=>{const match=text.match(pattern);return match?render(...match.slice(1)):null;};

export function translateInterfaceText(text,labels=interfaceLabels){
 if(!japanese.test(text))return text;
 if(labels.has(text))return labels.get(text);
 const dynamic=[
  [/^復習 (\d+) · 新しい課題 (\d+) · 一日の新規枠は全モジュール共通$/, (due,newCount)=>`Reviews ${due} · New tasks ${newCount} · Daily new slots are shared across all modules`],
  [/^学習ステップが (\d+) 件あります。次の予定は (\d{1,2}:\d{2}) です。$/, (n,time)=>`${n} learning steps remain. The next is at ${time}.`],
  [/^(\d{1,2}:\d{2})まで待つ$/, time=>`Wait until ${time}`],
  [/^次の学習ステップは (\d{1,2}:\d{2}) です。予定はそのまま保存しています。$/,time=>`The next learning step is at ${time}. Its schedule is unchanged.`],
  [/^ほか(\d+)件$/,n=>`and ${n} more`],
  [/^(\d+) 課題$/,n=>`${n} tasks`],[/^(\d+) 回$/,n=>`${n} times`],
  [/^(\d+)分$/,n=>`${n} min`],[/^(\d+)時間$/,n=>`${n} hr`],[/^(\d+)日$/,n=>`${n} days`],[/^(\d+)画$/,n=>`${n} strokes`],
  [/^(\d+)件 · (\d+)〜(\d+)件を表示$/, (count,start,end)=>`Showing ${start}–${end} of ${count}`],
  [/^(\d+)件 · (\d+)〜(\d+)件$/, (count,start,end)=>`${start}–${end} of ${count}`],
  [/^語彙([\d,]+)件（わたしの言葉(\d+)件を含む）・文法(\d+)課題。(?:引き継いだ(\d+)件に、新しい言葉(\d+)件を追加しています。)?全文英訳は配布内容を表示しています。$/, (vocab,personal,grammar,base,added)=>`${vocab} vocabulary tasks (including ${personal} personal words) and ${grammar} grammar tasks. ${added?`${added} new words were added to ${base} carried-over words. `:''}Full English translations are included in the delivered content.`],
  [/^このプレビューは (\d+) 件の確認済み課題を表示します。全8,508課題の導入・コンテンツ検証は別途確認が必要です。$/,count=>`This preview shows ${count} verified tasks. Import and content checks for all 8,508 tasks require separate review.`],
  [/^この端末に保存 (\d+) · 未送信 (\d+) · 開発Worker受領 (\d+) · 適用 (\d+)\/(\d+)$/, (saved,pending,ack,applied,head)=>`Saved on device ${saved} · Unsent ${pending} · Development Worker received ${ack} · Applied ${applied}/${head}`],
  [/^この端末に保存 (\d+) · 未送信 (\d+) · Worker受領 (\d+) · 適用 (\d+)\/(\d+)$/, (saved,pending,ack,applied,head)=>`Saved on device ${saved} · Unsent ${pending} · Worker received ${ack} · Applied ${applied}/${head}`],
  [/^この端末に保存 (\d+) · 未送信 (\d+) · サーバー同期は未接続$/, (saved,pending)=>`Saved on device ${saved} · Unsent ${pending} · Server sync disconnected`],
  [/^このMacに保存 (\d+) · ローカル専用（クラウド未接続）$/,saved=>`Saved on this Mac ${saved} · Local only (cloud disconnected)`],
  [/^この端末に保存しました · (.+)$/,rating=>`Saved on this device · ${rating}`],
  [/^記録は採点に使われませんでした（(.+)）。$/,reason=>`The record was not used for grading (${translateInterfaceText(reason,labels)}).`],
  [/^(.+)の言葉$/,()=>`Word details`],
  [/^迷い → (.+)（予定を短縮）$/,rating=>`Hesitation → ${rating} (shorter interval)`],
  [/^この課題だけで (\d+) 回のつまずき。文脈を変える、ヒントを足す、休ませる。$/,n=>`${n} lapses on this task. Change the context, add a hint, or suspend it.`],
  [/^部品：(.+?)(?: · (\d+)画)?$/,(_parts,strokes)=>`Components: ${strokes?`${strokes} strokes`:''}`],
  [/^以前の回答 (\d+) 件 · 調べた言葉 (\d+) 件 · このアプリの新しい回答 (\d+) 件$/, (old,lookups,newCount)=>`Earlier answers ${old} · Looked-up words ${lookups} · New answers in this app ${newCount}`],
  [/^(.+) · 一日の新規 (\d+) · 読み方 (.+) · 全文英訳 (.+) · 文脈 (.+)$/, (deck,count,mode,gloss,zoom)=>`${deck} · ${count} new per day · Reading mode ${mode} · Full English translation ${gloss} · Context ${zoom}`],
  [/^(.+) · 評価 (\d+) · (.+)$/, (deck,rating,date)=>`${deck} · Grade ${rating} · ${date}`],
  [/^(.+) · (\d+)画$/, (parts,strokes)=>`${parts} · ${strokes} strokes`],
  [/^このMacに記録を保存 · 新規枠はこのMacの学習日ごとに割り当てます。クラウド同期は未接続です。$/,()=>`Records are saved on this Mac. New-card slots are assigned for each Mac study day. Cloud sync is disconnected.`],
  [/^学習者 (.+) · 開発Workerとペア設定したテスト専用の記録です。新規枠は認証済みWorkerから受け取り、共有ログの適用後に使います。$/,learner=>`Learner ${learner} · Test-only records paired with a development Worker. New slots are used after the authenticated Worker applies them to the shared log.`],
  [/^学習者 (.+) · 本番Workerとペア設定済み。新規枠はWorkerから受け取り、共有ログに適用してから使います。$/,learner=>`Learner ${learner} · Paired with the production Worker. New-card slots come from the Worker and are used after they are applied to the shared log.`],
  [/^このMacに記録を保存 · 本番Workerと接続済み。新規枠はWorkerから受け取り、共有ログに適用してから使います。$/,()=>`Records are saved on this Mac · Connected to the production Worker. New-card slots are received from the Worker and used after they are applied to the shared log.`],
  [/^このMacに記録を保存 · Worker未接続。既存の学習履歴を引き継ぐまで、新規枠はこのMacの学習日ごとに割り当てます。$/,()=>`Records are saved on this Mac · Worker not connected. Until the existing study history is carried over, new-card slots are allocated per study day on this Mac.`],
  [/^学習者 (.+) · テスト専用の保存領域 · 初回の新規枠はQA用の模擬割当です。$/,learner=>`Learner ${learner} · Test-only storage · Initial new slots are a simulated QA grant.`]
 ];
 for(const [pattern,render] of dynamic){const value=counted(text,pattern,render);if(value!==null)return value;}
 // Structured labels concatenate independent UI fragments with a middle dot.
 if(text.includes(' · ')){const parts=text.split(' · ');const translated=parts.map(part=>translateInterfaceText(part,labels));if(translated.every(part=>!japanese.test(part)))return translated.join(' · ');}
 return text;
}

/** Format interface copy only; source card and dictionary text never call this. */
export function formatInterfaceText(text,language='ja',labels=interfaceLabels){
 const english=translateInterfaceText(text,labels);
 return language==='en'?english:language==='both'&&english!==text?`${text} / ${english}`:text;
}
